// Helper: Escape XML special characters
export function escapeXml(unsafe) {
  if (unsafe === undefined || unsafe === null) return '';
  const str = String(unsafe);
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

// Helper: Ensure valid absolute RFC 3986 URL with http/https prefix
export function formatGoogleMerchantUrl(rawUrl, baseUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return baseUrl;
  let trimmed = rawUrl.trim();
  if (trimmed.startsWith('//')) {
    trimmed = `https:${trimmed}`;
  } else if (!trimmed.startsWith('http://') && !trimmed.startsWith('https://')) {
    const cleanBase = baseUrl.replace(/\/+$/, '');
    const cleanPath = trimmed.startsWith('/') ? trimmed : `/${trimmed}`;
    trimmed = `${cleanBase}${cleanPath}`;
  }
  try {
    const parsed = new URL(trimmed);
    return parsed.href;
  } catch {
    return trimmed;
  }
}

function getBaseUrl(req) {
  const host = req.headers.host || 'localhost:3000';
  const proto = (req.headers['x-forwarded-proto'] || 'https').split(',')[0].trim();
  return `${proto}://${host}`;
}

// GET /api/merchant/feed.xml
// Sirve el feed de productos en formato válido para Google Merchant Center
// (RSS 2.0 / XML con xmlns:g), a partir del catálogo embebido en build-time.
export async function feedXmlHandler(req, res) {
  try {
    const baseUrl = getBaseUrl(req);
    const rawStoreUrl = CONFIGURED_STORE_URL || baseUrl;
    const storeUrl = formatGoogleMerchantUrl(rawStoreUrl, baseUrl);

    res.setHeader('Content-Type', 'application/xml; charset=UTF-8');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', 'public, max-age=300, s-maxage=300');

    let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
    xml += `<rss xmlns:g="http://base.google.com/ns/1.0" version="2.0">\n`;
    xml += `  <channel>\n`;
    xml += `    <title>${escapeXml(STORE_NAME)}</title>\n`;
    xml += `    <link>${escapeXml(storeUrl)}</link>\n`;
    xml += `    <description>Catálogo de productos de ${escapeXml(STORE_NAME)} para Google Merchant Center</description>\n`;
    xml += `    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>\n`;

    const activeList = PRODUCTS.filter((p) => !p.status || p.status === 'active');

    if (activeList.length === 0) {
      xml += `    <item>\n`;
      xml += `      <g:id>sample-item-1</g:id>\n`;
      xml += `      <g:title>Producto de Muestra</g:title>\n`;
      xml += `      <g:description>Todavía no hay productos activos cargados en la tienda. Agregá productos activos, volvé a exportar y redesplegá para que aparezcan acá.</g:description>\n`;
      xml += `      <g:link>${escapeXml(storeUrl)}</g:link>\n`;
      xml += `      <g:image_link>https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800</g:image_link>\n`;
      xml += `      <g:availability>in_stock</g:availability>\n`;
      xml += `      <g:price>1000.00 ${escapeXml(CURRENCY)}</g:price>\n`;
      xml += `      <g:condition>new</g:condition>\n`;
      xml += `      <g:brand>${escapeXml(STORE_NAME)}</g:brand>\n`;
      xml += `    </item>\n`;
    } else {
      for (const prod of activeList) {
        const prodId = prod.id || prod.sku || `prod-${Math.random().toString(36).substring(2, 8)}`;
        const title = prod.name || prod.title || 'Producto';
        const desc = prod.description || prod.shortDescription || title;
        const price = Number(prod.price) || 0;
        const comparePrice = Number(prod.comparePrice) || 0;
        const stock = prod.stock !== undefined ? Number(prod.stock) : 10;
        const availability = stock > 0 ? 'in_stock' : 'out_of_stock';

        // URL canónica exacta a la página HTML del producto
        const cleanBase = storeUrl.replace(/\/+$/, '');
        const rawProdLink = `${cleanBase}/producto-${encodeURIComponent(prodId)}.html`;
        const prodLink = formatGoogleMerchantUrl(rawProdLink, baseUrl);

        const rawImg =
          prod.image || (prod.images && prod.images[0]) || 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=800';
        const imageLink = formatGoogleMerchantUrl(rawImg, baseUrl);

        const brand = prod.marca || prod.proveedor || STORE_NAME;

        xml += `    <item>\n`;
        xml += `      <g:id>${escapeXml(prodId)}</g:id>\n`;
        xml += `      <g:title>${escapeXml(title)}</g:title>\n`;
        xml += `      <g:description>${escapeXml(String(desc).replace(/<[^>]*>?/gm, '').slice(0, 5000))}</g:description>\n`;
        xml += `      <g:link>${escapeXml(prodLink)}</g:link>\n`;
        xml += `      <g:image_link>${escapeXml(imageLink)}</g:image_link>\n`;
        xml += `      <g:condition>new</g:condition>\n`;
        xml += `      <g:availability>${availability}</g:availability>\n`;
        xml += `      <g:price>${price.toFixed(2)} ${escapeXml(CURRENCY)}</g:price>\n`;
        if (comparePrice > price) {
          xml += `      <g:sale_price>${price.toFixed(2)} ${escapeXml(CURRENCY)}</g:sale_price>\n`;
        }
        xml += `      <g:brand>${escapeXml(brand)}</g:brand>\n`;
        if (prod.barcode || prod.sku) {
          xml += `      <g:gtin>${escapeXml(prod.barcode || prod.sku)}</g:gtin>\n`;
          xml += `      <g:mpn>${escapeXml(prod.sku || prod.barcode)}</g:mpn>\n`;
        } else {
          xml += `      <g:identifier_exists>no</g:identifier_exists>\n`;
        }
        if (prod.category) {
          xml += `      <g:product_type>${escapeXml(prod.category)}</g:product_type>\n`;
        }
        xml += `    </item>\n`;
      }
    }

    xml += `  </channel>\n`;
    xml += `</rss>`;

    return res.status(200).send(xml);
  } catch (err) {
    res.setHeader('Content-Type', 'application/xml; charset=UTF-8');
    return res.status(500).send(`<?xml version="1.0" encoding="UTF-8"?><error>${escapeXml(err.message)}</error>`);
  }
}
